import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·5","description":"易小帖 - 卷四·5","frontmatter":{"title":"卷四·5","description":"易小帖 - 卷四·5"},"headers":[],"relativePath":"zh/classics/yixiaotie/099.md","filePath":"zh/classics/yixiaotie/099.md"}'),o={name:"zh/classics/yixiaotie/099.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·5",tabindex:"-1"},[r("卷四·5 "),e("a",{class:"header-anchor",href:"#卷四·5","aria-label":"Permalink to “卷四·5”"},"​")],-1),e("p",null,"明來知德謂：觀生，觀陰陽相生之正應也。三之生指上，五之生指二。上之生指三，則惟二五為陰陽相應，三上並陰，彼此不應，且相應非相生也。何氏《訂詁》謂：一陰姤生二陰遯，二陰遯生三陰否，三陰否生四陰觀，則觀之四陰乃否所生也。三之觀即觀四也。然六陰遞生，皆自生耳，非必前陰生後陰也，且三觀四，何為乎及九五上九。觀字又皆以陽觀陰，謂四陰皆從陽生，則益牽強矣。始知推易之妙，自有至理，豈逐節撰造，比之盲子騎瞎馬，東驀西闖，無定在耶。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
